css:
.p17-page { display: grid; grid-template-rows: auto 1fr; min-height: 100cqh; overflow-x: clip; }
.p17-page > .deck { grid-row: 2; align-self: center; }
.p17-top { display: grid; gap: var(--s-2); width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3) var(--s-3) 0; grid-row: 1; }
.p17-top:empty { display: none; }
.p17-strip { --p17-sh: 9rem; }
.p17-strip--b { --p17-sh: 4.5rem; }
.p17-strip .deck { --card: max(var(--card-min), min(var(--card-max), calc(100cqw - 2rem), calc(100cqh - 2rem - var(--peek) - var(--s-3) - var(--controls-h) - var(--p17-sh)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p17-strip { --p17-sh: 17rem; } .p17-strip--b { --p17-sh: 6rem; } }
@media (max-width: 21.25rem) { .p17-strip { --p17-sh: 22rem; } .p17-strip--b { --p17-sh: 7rem; } }
.p17-win .deck-card__head { margin-top: 0; }
.p17-face { gap: var(--s-2); }
.p17-body { flex: 1 1 auto; min-height: 0; overflow: auto; display: grid; grid-auto-rows: min-content; gap: var(--s-3); align-content: start; padding-block: var(--s-1) var(--s-2); border-bottom: var(--w1) solid var(--rule); }
.p17-msg { flex: none; display: grid; gap: var(--s-2); }
.p17-msg:empty { display: none; }
.p17-foot { flex: none; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: var(--s-2); }
.dialog__foot.p17-foot2 { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); }
.p17-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -1); }
.p17-area { position: relative; }
.p17-count { position: absolute; right: var(--s-2); bottom: var(--s-1); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); pointer-events: none; background: var(--white); padding-inline: var(--s-1); }
.p17-count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.textarea.p17-ta { min-height: 4rem; padding-bottom: 1.375rem; resize: none; }
.p17-pair { display: grid; grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr)); gap: var(--s-3); align-items: start; }
.p17-pair .field { grid-template-columns: minmax(0, 1fr); }
.p17-pair .select { height: auto; min-width: 0; padding-block: var(--s-2); }
.p17-pair .select > span { min-width: 0; flex: 1 1 auto; overflow: hidden; overflow-wrap: anywhere; }
.p17-pair .select .motive { display: flex; max-width: 100%; }
.p17-pair + .menu { margin-top: calc(var(--s-2) * -1); }
.p17-full { grid-column: 1 / -1; }
.textarea.p17-name { min-height: var(--ctl-h); padding: var(--s-2) var(--s-3); resize: none; overflow-wrap: anywhere; }
.btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p17-tipw { position: relative; display: flex; min-width: 0; }
.p17-tipw > .btn { flex: 1 1 auto; width: 100%; }
.p17-tip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.p17-win .hint { font-size: var(--fs-small); }
.p17-fade { opacity: 0.5; }
.p17-pressed { border-width: var(--w2); border-color: var(--ink); text-decoration: underline; text-underline-offset: 0.25em; }

.dialog.p17-dlg { max-height: 100%; }
.dialog__foot.p17-foot3 { flex-direction: column; }
.dialog__foot.p17-foot3 > * { flex: none; }
.p17-dlg .dialog__body p + p { color: var(--muted); }
.p17-dlg .banner { padding-inline: var(--s-3); }
.p17-dlg .dialog__foot .p17-tipw { position: relative; }
.p17-dtip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }

.p-menuwrap { position: relative; display: flex; }
.ibtn.is-open { border: var(--w2) solid var(--ink); }
.p17-menu { position: absolute; z-index: 30; right: 0; top: calc(100% + var(--s-1)); min-width: 12rem; max-width: calc(100cqw - var(--s-5)); }
.p17-menu .menu__item { min-height: var(--row-h); }

.p17-ring { outline: var(--focus-ring); outline-offset: var(--focus-offset); }
.p17-dlg .dialog__body { gap: var(--s-3); }
.p17-dlg .banner { padding-inline: var(--s-3); }
.p17-dlg .p17-tipw { flex: 1 1 0; }

@media (max-width: 21.25rem) {
  .composer { gap: var(--s-1); padding-inline: var(--s-1); }
  .composer .input { padding-inline: var(--s-1); }
  .composer .input::placeholder { font-size: var(--fs-small); }
}

.p17-dlg .dialog__foot:has(.p17-tipw) { display: grid; grid-template-columns: 1fr 1fr; }
.p17-dlg .dialog__foot .p17-tipw { display: contents; }
.p17-dlg .dialog__foot .p17-tipw > .tip { position: static; translate: none; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; text-align: start; }

@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p17-dlg .dialog__head { flex-wrap: wrap; }
  .p17-dlg .dialog__head > .ibtn { order: -1; margin-inline-start: auto; }
  .p17-dlg .dialog__title { flex: 1 1 100%; }
}
@media (max-width: 21.25rem) { .scrim { padding: var(--s-3); } }

.deck-card .rec__value .pg { margin: var(--s-1) 0 var(--s-1) auto; }
@container card (max-width: 24rem) { .deck-card .rec__value .pg { margin-left: 0; } }
.p17-progbar { display: grid; gap: var(--s-1); }
.p17-progbar .pg { margin-bottom: var(--s-1); }
